#!/bin/bash
sed -i 's/Icon(imageVector = Icons.Default.QrCode, contentDescription = "QR Code", modifier = Modifier.size(120.dp), tint = com.example.ui.theme.DarkGreen)/val qrBitmap = generateQRCode(customer?.email ?: "guest", 400)\n                    if (qrBitmap != null) {\n                        androidx.compose.foundation.Image(bitmap = qrBitmap.asImageBitmap(), contentDescription = "QR Code", modifier = Modifier.size(120.dp))\n                    } else {\n                        Icon(imageVector = Icons.Default.QrCode, contentDescription = "QR Code", modifier = Modifier.size(120.dp), tint = com.example.ui.theme.DarkGreen)\n                    }/g' app/src/main/java/com/example/CustomerDashboardScreen.kt
